// Process incoming knowledge base content
const data = $input.first().json.body;

// Extract and validate required fields
const title = data.title;
const content = data.content;
const contentType = data.content_type || 'general';
const category = data.category || 'general';
const tenantId = data.tenant_id;
const source = data.source || 'manual';
const tags = data.tags || [];

// Validate required fields
if (!title || !content || !tenantId) {
  throw new Error('Missing required fields: title, content, tenant_id');
}

// Split content into chunks if it's too long (>1000 chars)
const maxChunkSize = 1000;
const chunks = [];

if (content.length <= maxChunkSize) {
  chunks.push({
    title: title,
    content: content,
    content_type: contentType,
    category: category,
    tenant_id: tenantId,
    source: source,
    tags: JSON.stringify(tags),
    chunk_index: 0,
    total_chunks: 1
  });
} else {
  // Split into chunks
  const sentences = content.split(/[.!?]+/);
  let currentChunk = '';
  let chunkIndex = 0;

  sentences.forEach((sentence, index) => {
    if (currentChunk.length + sentence.length > maxChunkSize && currentChunk.length > 0) {
      chunks.push({
        title: `${title} (Part ${chunkIndex + 1})`,
        content: currentChunk.trim(),
        content_type: contentType,
        category: category,
        tenant_id: tenantId,
        source: source,
        tags: JSON.stringify(tags),
        chunk_index: chunkIndex,
        total_chunks: 0 // Will be updated later
      });
      currentChunk = sentence;
      chunkIndex++;
    } else {
      currentChunk += sentence + '.';
    }
  });

  // Add the last chunk
  if (currentChunk.trim()) {
    chunks.push({
      title: `${title} (Part ${chunkIndex + 1})`,
      content: currentChunk.trim(),
      content_type: contentType,
      category: category,
      tenant_id: tenantId,
      source: source,
      tags: JSON.stringify(tags),
      chunk_index: chunkIndex,
      total_chunks: 0
    });
  }

  // Update total_chunks for all chunks
  chunks.forEach(chunk => {
    chunk.total_chunks = chunks.length;
  });
}

return chunks.map(chunk => ({ json: chunk }));

// Format data for database insertion
const chunk = $input.first().json;
const embedding = $('Generate Embeddings').first().json.embedding;

// Format embedding as PostgreSQL vector
const vectorString = `[${embedding.join(',')}]`;

return {
  json: {
    tenant_id: chunk.tenant_id,
    title: chunk.title,
    content: chunk.content,
    content_type: chunk.content_type,
    embedding: vectorString,
    source: chunk.source,
    category: chunk.category,
    tags: chunk.tags,
    is_active: true,
    version: 1,
    access_count: 0
  }
};

